#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "correlation.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto n_vec = noarr::vector<'n'>();
constexpr auto m_vec = noarr::vector<'m'>();
constexpr auto p_vec = noarr::vector<'p'>();
constexpr auto q_vec = noarr::vector<'q'>();

struct tuning {
	// data: n x m  (rows: n, columns/features: m), row-major (m contiguous)
	DEFINE_PROTO_STRUCT(data_layout, m_vec ^ n_vec);
	// corr: p x q (both run over features 0..M-1), row-major (q contiguous)
	DEFINE_PROTO_STRUCT(corr_layout, q_vec ^ p_vec);
	// 1D vectors over features
	DEFINE_PROTO_STRUCT(vec_layout, m_vec);
} tuning;


// initialization function
// float_n <- N (number of rows in data)
// data[i][j] = (DATA_TYPE)(i*j)/M + i;
void init_array(num_t &float_n, auto data) {
	using namespace noarr;

	// N is the length in the 'n' dimension
	float_n = static_cast<num_t>(data | get_length<'n'>());

	// M is the length in the 'm' dimension (compute once, reuse in the loop)
	const num_t M_len = static_cast<num_t>(data | get_length<'m'>());

	// Default traverser order is row-major for this layout ('n' outer, 'm' inner),
	// which matches the physical layout (m contiguous).
	traverser(data).for_each([=](auto state) {
		auto [i, j] = get_indices<'n', 'm'>(state);

		data[state] =
			static_cast<num_t>(
				static_cast<num_t>(i * j) / M_len +
				static_cast<num_t>(i)
			);
	});
}


// main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_correlation(num_t float_n, auto data, auto corr, auto mean, auto stddev) {
	using namespace noarr;

	const num_t eps         = SCALAR_VAL(0.1);
	const num_t inv_float_n = SCALAR_VAL(1.0) / float_n; // 1/N used in multiple places
	const num_t sqrt_n      = SQRT_FUN(float_n);         // sqrt(N) computed once

#pragma scop

	// ------------------------------------------------------------------------
	// mean[j] = 1/N * sum_i data[i][j]
	// Optimized for row-major traversal:
	//  1) zero mean once
	//  2) traverse data row-major and accumulate into mean
	//  3) scale by 1/N
	// ------------------------------------------------------------------------

	// 1) mean[:] = 0
	traverser(mean).for_each([=](auto s_m) {
		mean[s_m] = SCALAR_VAL(0.0);
	});

	// 2) accumulate: for all (i, j): mean[j] += data[i][j]
	//    traverser(data, mean).for_each visits elements row-major (n outer, m inner)
	traverser(data, mean).for_each([=](auto state) {
		// state has 'n' and 'm'; mean ignores 'n'
		mean[state] += data[state];
	});

	// 3) scale each feature by 1/N
	traverser(mean).for_each([=](auto s_m) {
		mean[s_m] *= inv_float_n;
	});

	// ------------------------------------------------------------------------
	// stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	// stddev[j] = 1.0 if stddev[j] <= eps
	//
	// Again use row-major traversal for better locality:
	//  1) zero stddev once
	//  2) accumulate squared deviations over all (i, j)
	//  3) finalize stddev per feature
	// ------------------------------------------------------------------------

	// 1) stddev[:] = 0
	traverser(stddev).for_each([=](auto s_m) {
		stddev[s_m] = SCALAR_VAL(0.0);
	});

	// 2) accumulate squared deviations
	traverser(data, mean, stddev).for_each([=](auto state) {
		num_t diff = data[state] - mean[state];
		stddev[state] += diff * diff;
	});

	// 3) finalize: stddev[j] = sqrt( stddev[j] / N ), clamp to 1.0 if <= eps
	traverser(stddev).for_each([=](auto s_m) {
		stddev[s_m] = SQRT_FUN(stddev[s_m] * inv_float_n);
		stddev[s_m] = stddev[s_m] <= eps ? SCALAR_VAL(1.0) : stddev[s_m];
	});

	// ------------------------------------------------------------------------
	// Center and reduce the column vectors:
	//   data[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
	//
	// We use a single row-major traversal and the precomputed sqrt_n.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).for_each([=](auto state) {
		data[state] -= mean[state];
		data[state] /= (sqrt_n * stddev[state]);
	});

	// ------------------------------------------------------------------------
	// Compute the m x m correlation matrix:
	//
	// for (i = 0; i < M-1; i++) {
	//   corr[i][i] = 1.0;
	//   for (j = i+1; j < M; j++) {
	//     corr[i][j] = 0.0;
	//     for (k = 0; k < N; k++)
	//       corr[i][j] += data[k][i] * data[k][j];
	//     corr[j][i] = corr[i][j];
	//   }
	// }
	// corr[M-1][M-1] = 1.0;
	//
	// Optimizations:
	//   - avoid constructing a new traverser for each (i, j) pair
	//   - use a single traverser over (data_p, data_q, corr)
	//   - restrict 'q' dimension per-row using slice<'q'>(i+1, M-(i+1))
	//     so we iterate only j > i (upper triangle) without inner if
	// ------------------------------------------------------------------------

	const std::size_t m_len = corr | get_length<'p'>(); // M

	// Create views on data so that the feature index matches corr's 'p'/'q'
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

	// First, set the diagonal: corr[i][i] = 1.0 for all i
	traverser(corr).template for_dims<'p'>([=](auto trav_p) {
		auto state_p = trav_p.state();
		auto i = noarr::get_index<'p'>(state_p);

		corr[noarr::idx<'p', 'q'>(i, i)] = SCALAR_VAL(1.0);
	});

	// Now compute the upper triangle and mirror to the lower triangle.
	// Use a combined traverser to reuse the same traversal infrastructure.
	traverser(data_p, data_q, corr).template for_dims<'p'>([=](auto trav_p) {
		auto state_p = trav_p.state();
		auto i = noarr::get_index<'p'>(state_p);

		// No off-diagonal elements in the last row
		if (i + 1 >= m_len)
			return;

		// Restrict 'q' to j in [i+1, m_len). Using slice keeps the actual
		// 'q' indices in the state (we still see j >= i+1), but skips j <= i.
		auto trav_q = trav_p.order(noarr::slice<'q'>(i + 1, m_len - (i + 1)));

		// For each j > i
		trav_q.template for_dims<'q'>([=](auto trav_pq) {
			auto state_pq = trav_pq.state();
			auto j = noarr::get_index<'q'>(state_pq);

			// corr[i][j] = 0.0;
			corr[state_pq] = SCALAR_VAL(0.0);

			// Inner loop over k = 0 .. N-1 along dimension 'n'
			// (p = i, q = j are fixed in trav_pq)
			trav_pq.for_each([=](auto state_n) {
				// state_n has 'n', 'p', 'q'; data_p uses (n,p), data_q uses (n,q)
				corr[state_pq] += data_p[state_n] * data_q[state_n];
			});

			// corr[j][i] = corr[i][j]; (symmetry)
			corr[noarr::idx<'p', 'q'>(j, i)] = corr[state_pq];
		});
	});

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t float_n;

	// set all relevant lengths
	auto set_lengths =
		noarr::set_length<'n'>(n) ^
		noarr::set_length<'m'>(m) ^
		noarr::set_length<'p'>(m) ^
		noarr::set_length<'q'>(m);

	// allocate bags for data, correlation matrix, mean, and stddev
	auto data   = noarr::bag(noarr::scalar<num_t>() ^ tuning.data_layout ^ set_lengths);
	auto corr   = noarr::bag(noarr::scalar<num_t>() ^ tuning.corr_layout ^ set_lengths);
	auto mean   = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths);
	auto stddev = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths);

	// initialize data
	init_array(float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_correlation(float_n, data.get_ref(), corr.get_ref(), mean.get_ref(), stddev.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (correlation matrix) if requested
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'p' (row index) to top for a natural row-major printout
		noarr::serialize_data(std::cerr, corr.get_ref() ^ noarr::hoist<'p'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
