	const num_t M_len = static_cast<num_t>(m_len);

	// Default traverser order on data (dims 'n','m') is row-major:
	// 'n' outer, 'm' inner, so we get good locality in the contiguous 'm' dimension.
	traverser(data).for_each([=](auto state) {
		auto [i, j] = get_indices<'n', 'm'>(state);

		data[state] = static_cast<num_t>(
			static_cast<num_t>(i * j) / M_len + static_cast<num_t>(i));
	});
