// main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_correlation(num_t float_n, auto data, auto corr, auto mean, auto stddev) {
	using namespace noarr;

	const num_t eps = SCALAR_VAL(0.1);

#pragma scop

	// ------------------------------------------------------------------------
	// 1) Compute per-feature means and standard deviations.
	//
	// We do this in a cache-friendly single pass over the data:
	//   mean_acc[j]   = sum_i data[i][j]
	//   stddev_acc[j] = sum_i data[i][j]^2
	// and then convert:
	//   mean[j]   = mean_acc[j] / N
	//   var[j]    = stddev_acc[j] / N - mean[j]^2
	//   stddev[j] = sqrt(max(var[j], 0))
	//   stddev[j] = 1.0 if stddev[j] <= eps
	//
	// This replaces the original two passes (mean + stddev) with one pass,
	// improving data locality while preserving the mathematical result
	// up to floating-point round-off.
	// ------------------------------------------------------------------------

	// Initialize accumulators to zero.
	traverser(mean, stddev).for_each([&](auto state_m) {
		mean[state_m]   = SCALAR_VAL(0.0);
		stddev[state_m] = SCALAR_VAL(0.0);
	});

	// Accumulate sums and squared sums in a row-major traversal:
	// outer 'n' (rows), inner 'm' (features, contiguous).
	traverser(data, mean, stddev).template for_dims<'n'>([&](auto trav_n) {
		trav_n.for_each([&](auto state) {
			const num_t x = data[state];
			mean[state]   += x;      // sum of x
			stddev[state] += x * x;  // sum of x^2
		});
	});

	// Finalize mean and stddev from accumulated sums.
	traverser(mean, stddev).for_each([&](auto state_m) {
		const num_t sum  = mean[state_m];
		const num_t sum2 = stddev[state_m];

		num_t mu   = sum / float_n;
		num_t var  = sum2 / float_n - mu * mu;

		// Guard against small negative variance from round-off.
		if (var < SCALAR_VAL(0.0))
			var = SCALAR_VAL(0.0);

		num_t sigma = SQRT_FUN(var);
		if (sigma <= eps)
			sigma = SCALAR_VAL(1.0);

		mean[state_m]   = mu;
		stddev[state_m] = sigma;
	});

	// ------------------------------------------------------------------------
	// 2) Center and reduce the column vectors:
	//
	//   data[i][j] <- (data[i][j] - mean[j]) / (sqrt(N) * stddev[j])
	//
	// To avoid an expensive division in the inner loop, we precompute
	//
	//   scale_inv[j] = 1 / (sqrt(N) * stddev[j])
	//
	// and overwrite stddev[j] with scale_inv[j]. Afterwards, we apply
	//
	//   data[i][j] <- (data[i][j] - mean[j]) * scale_inv[j]
	//
	// in a row-major traversal for good spatial locality.
	// ------------------------------------------------------------------------

	const num_t sqrt_n = SQRT_FUN(float_n);

	// Precompute inverse scaling factors into stddev[j].
	traverser(stddev).for_each([&](auto state_m) {
		const num_t sigma = stddev[state_m]; // already >= eps
		stddev[state_m] = SCALAR_VAL(1.0) / (sqrt_n * sigma);
	});

	// Apply centering and scaling: row-major over data.
	traverser(data, mean, stddev).template for_dims<'n'>([&](auto trav_n) {
		trav_n.for_each([&](auto state) {
			const num_t x        = data[state];
			const num_t centered = x - mean[state];
			// stddev now holds the inverse scale factor 1/(sqrt(N)*orig_stddev)
			data[state] = centered * stddev[state];
		});
	});

	// ------------------------------------------------------------------------
	// 3) Compute the m x m correlation matrix:
	//
	// After step (2), columns of 'data' are normalized to zero mean and
	// unit variance (up to eps). The correlation between features i and j
	// is just the dot product over rows:
	//
	//   corr[i][j] = sum_k data[k][i] * data[k][j]
	//
	// We compute this using a row-based algorithm:
	//
	//   for each row k:
	//     for each feature i:
	//       for each feature j > i:
	//         corr[i][j] += data[k][i] * data[k][j];
	//         corr[j][i] += data[k][i] * data[k][j];
	//
	// This visits each row of 'data' (which is stored row-major) once,
	// providing good cache locality for the input matrix. The symmetric
	// updates maintain corr[j][i] = corr[i][j]. Finally, we set the
	// diagonal elements corr[i][i] = 1.0 explicitly, as in the original
	// code.
	// ------------------------------------------------------------------------

	// Zero the whole correlation matrix once.
	traverser(corr).for_each([&](auto state_pq) {
		corr[state_pq] = SCALAR_VAL(0.0);
	});

	// Create feature-indexed views on data so that its feature dimension
	// matches corr's 'p'/'q' dimensions.
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

	// Row-based accumulation: outer 'n' (rows), then 'p' (feature i),
	// then 'q' (feature j). We only use pairs with j > i to avoid
	// double-counting and to keep the diagonal untouched.
	noarr::traverser(data_p, data_q, corr).template for_dims<'n'>([&](auto trav_n) {

		// Fix row index 'n'; iterate over feature index 'p' (i).
		trav_n.template for_dims<'p'>([&](auto trav_np) {
			auto state_np = trav_np.state();
			const std::size_t i = noarr::get_index<'p'>(state_np);

			// Value of feature i in this row.
			const num_t xi = data_p[state_np];

			// Now iterate over feature index 'q' (j).
			trav_np.template for_dims<'q'>([&](auto trav_npq) {
				auto state_npq = trav_npq.state();
				const std::size_t j = noarr::get_index<'q'>(state_npq);

				// Only handle upper triangle (j > i). Diagonal is set later.
				if (j > i) {
					const num_t xj   = data_q[state_npq];
					const num_t prod = xi * xj;

					// Update upper triangle entry corr[i][j]
					corr[state_npq] += prod;

					// And mirror to lower triangle corr[j][i]
					corr[noarr::idx<'p', 'q'>(j, i)] += prod;
				}
			});
		});
	});

	// Set the diagonal to 1.0 explicitly (corr[i][i] = 1.0 for all i).
	noarr::traverser(corr).template for_dims<'p'>([&](auto trav_p) {
		auto state_p         = trav_p.state();
		const std::size_t i  = noarr::get_index<'p'>(state_p);
		corr[noarr::idx<'p', 'q'>(i, i)] = SCALAR_VAL(1.0);
	});

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t float_n;

	// set all relevant lengths
	auto set_lengths =
		noarr::set_length<'n'>(n) ^
		noarr::set_length<'m'>(m) ^
		noarr::set_length<'p'>(m) ^
		noarr::set_length<'q'>(m);

	// allocate bags for data, correlation matrix, mean, and stddev
	auto data   = noarr::bag(noarr::scalar<num_t>() ^ tuning.data_layout ^ set_lengths);
	auto corr   = noarr::bag(noarr::scalar<num_t>() ^ tuning.corr_layout ^ set_lengths);
	auto mean   = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths);
	auto stddev = noarr::bag(noarr::scalar<num_t>() ^ tuning.vec_layout  ^ set_lengths);

	// initialize data
	init_array(float_n, data.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_correlation(float_n, data.get_ref(), corr.get_ref(), mean.get_ref(), stddev.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

