	const std::size_t N_len = data | get_length<'n'>();
	const std::size_t M_len_size = data | get_length<'m'>();

	float_n = static_cast<num_t>(N_len);
	const num_t M_len = static_cast<num_t>(M_len_size);

	noarr::traverser(data).for_each([=](auto state) {
		auto [i, j] = get_indices<'n', 'm'>(state);

		// Original formula: (DATA_TYPE)(i*j)/M + i;
		data[state] = static_cast<num_t>(
			static_cast<num_t>(i * j) / M_len + static_cast<num_t>(i));
	});
}


// main computational kernel
// NOTE: an extra 1D vector 'scale' is used to store 1/(sqrt(N)*stddev[j])
//       This removes an expensive division per element in the centering step
//       while keeping the contents of 'stddev' identical to the original code.
[[gnu::flatten, gnu::noinline]]
void kernel_correlation(num_t float_n, auto data, auto corr, auto mean, auto stddev, auto scale) {
	using namespace noarr;

	const num_t eps          = SCALAR_VAL(0.1);
	const num_t inv_float_n  = SCALAR_VAL(1.0) / float_n;
	const num_t sqrt_float_n = SQRT_FUN(float_n);

#pragma scop

	// ------------------------------------------------------------------------
	// mean[j] = 1/N * sum_i data[i][j]
	// Use a scalar accumulator instead of repeatedly reading/writing mean[j]
	// ------------------------------------------------------------------------
	traverser(data).template for_dims<'m'>([=](auto trav_m) {
		// trav_m has 'm' fixed (one feature column)
		auto state_m = trav_m.state();

		num_t sum = SCALAR_VAL(0.0);

		trav_m.for_each([&](auto state) {
			// state has 'n' and 'm'
			sum += data[state];
		});

		mean[state_m] = sum * inv_float_n;
	});

	// ------------------------------------------------------------------------
	// stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	// stddev[j] = 1.0 if stddev[j] <= eps
	// Again use a scalar accumulator to minimize memory traffic.
	// ------------------------------------------------------------------------
	traverser(data, mean).template for_dims<'m'>([=](auto trav_m) {
		auto state_m = trav_m.state();

		num_t sum_sq = SCALAR_VAL(0.0);

		trav_m.for_each([&](auto state) {
			num_t diff = data[state] - mean[state];
			sum_sq += diff * diff;
		});

		num_t variance = sum_sq * inv_float_n;
		num_t sigma    = SQRT_FUN(variance);

		if (sigma <= eps)
			sigma = SCALAR_VAL(1.0);

		stddev[state_m] = sigma;
	});

	// ------------------------------------------------------------------------
	// Precompute per-feature scaling factor:
	//   scale[j] = 1 / (sqrt(N) * stddev[j])
	//
	// This converts the expensive division in the centering step into a
	// multiplication, while keeping stddev[j] itself unchanged.
	// ------------------------------------------------------------------------
	traverser(stddev, scale).template for_dims<'m'>([=](auto trav_m) {
		auto state_m = trav_m.state();
		num_t sigma  = stddev[state_m]; // already >= eps

		scale[state_m] = SCALAR_VAL(1.0) / (sqrt_float_n * sigma);
	});

	// ------------------------------------------------------------------------
	// Center and reduce the column vectors:
	//   data[i][j] = (data[i][j] - mean[j]) * scale[j]
	// We traverse rows ('n') outermost to keep accesses to data row-major.
	// ------------------------------------------------------------------------
	traverser(data, mean, scale).template for_dims<'n'>([=](auto trav_n) {
		// trav_n has 'n' fixed; iterate over 'm' in row-major order
		trav_n.for_each([&](auto state) {
			num_t centered = data[state] - mean[state];
			data[state]    = centered * scale[state];
		});
	});

	// ------------------------------------------------------------------------
	// Compute the m x m correlation matrix:
	//
	// corr[p][q] = sum_k data[k][p] * data[k][q]   for q > p
	// corr[q][p] = corr[p][q]                      (symmetry)
	// corr[p][p] = 1.0                             (by definition)
	//
	// Compared to the original code, we reorganize the traversal as:
	//   for each row n
	//     for each feature p
	//       val_p = data[n][p]         (reused over q)
	//       for each feature q > p
	//         corr[p][q] += val_p * data[n][q]
	//
	// Implemented entirely with Noarr traversers; the domain restriction
	// (q > p) is enforced by a simple conditional.
	// ------------------------------------------------------------------------

	const std::size_t m_len = corr | get_length<'p'>(); // M

	// Views on data so that the feature index matches corr's 'p'/'q'
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

	// Initialize entire correlation matrix to zero
	traverser(corr).for_each([=](auto state) {
		corr[state] = SCALAR_VAL(0.0);
	});

	// Accumulate the upper triangular part (q > p) using an outer loop over rows
	noarr::traverser(corr, data_p, data_q).template for_dims<'n'>([=](auto trav_n) {
		// 'n' fixed here (one observation / row)
		trav_n.template for_dims<'p'>([=](auto trav_np) {
			// 'n' and 'p' fixed here
			auto state_np = trav_np.state();
			const std::size_t p = noarr::get_index<'p'>(state_np);

			// Value of feature p for this row, reused across all q
			const num_t val_p = data_p[state_np];

			// Iterate all possible q; only update for q > p
			trav_np.template for_dims<'q'>([=](auto trav_npq) {
				auto state_npq = trav_npq.state(); // has 'n', 'p', 'q'
				const std::size_t q = noarr::get_index<'q'>(state_npq);

				if (q > p) {
					corr[state_npq] += val_p * data_q[state_npq];
				}
			});
		});
	});

	// Enforce symmetry: corr[q][p] = corr[p][q] for q > p
	traverser(corr).template for_dims<'p', 'q'>([=](auto trav_pq) {
		auto state_pq = trav_pq.state();
		const std::size_t p = noarr::get_index<'p'>(state_pq);
		const std::size_t q = noarr::get_index<'q'>(state_pq);

		if (q > p) {
			corr[noarr::idx<'p', 'q'>(q, p)] = corr[state_pq];
		}
	});

	// Set all diagonal elements corr[p][p] = 1.0 (matching original semantics)
	if (m_len > 0) {
		traverser(corr).template for_dims<'p', 'q'>([=](auto trav_pq) {
			auto state_pq = trav_pq.state();
			const std::size_t p = noarr::get_index<'p'>(state_pq);
			const std::size_t q = noarr::get_index<'q'>(state_pq);

			if (p == q) {
				corr[state_pq] = SCALAR_VAL(1.0);
			}
		});
	}

#pragma endscop
}

} // namespace

