}


// main computational kernel
//
// Steps (same math as the original kernel, but with improved data locality):
//
// 1) mean[j]   = 1/N * sum_i data[i][j]
// 2) stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
//    if stddev[j] <= eps then stddev[j] = 1
//    We then store  1 / (sqrt(N) * stddev[j])  into the array `stddev`
// 3) data[i][j] = (data[i][j] - mean[j]) * stddev[j]
//    (i.e. scale by the precomputed inverse instead of dividing)
// 4) corr = data^T * data, but we only form the upper triangle and mirror it.
//    Diagonal elements are set to 1 explicitly.
//
[[gnu::flatten, gnu::noinline]]
void kernel_correlation(num_t float_n, auto data, auto corr, auto mean, auto stddev) {
	using namespace noarr;

	const num_t eps        = SCALAR_VAL(0.1);
	const num_t one        = SCALAR_VAL(1.0);
	const num_t zero       = SCALAR_VAL(0.0);
	const num_t inv_float_n = one / float_n;
	const num_t inv_sqrt_n  = one / SQRT_FUN(float_n);

#pragma scop

	// ------------------------------------------------------------------------
	// 1) mean[j] = 1/N * sum_i data[i][j]
	//    Implemented in three passes:
	//      - zero mean
	//      - accumulate all data[i][j] in row-major order
	//      - scale by 1/N
	// ------------------------------------------------------------------------

	// mean[j] = 0
	traverser(mean).for_each([&](auto s_m) {
		mean[s_m] = zero;
	});

	// Accumulate sum over all (i,j) in row-major order ('n','m')
	traverser(data, mean).for_each([&](auto s_nm) {
		// `mean` only cares about 'm'; extra 'n' index is ignored
		mean[s_nm] += data[s_nm];
	});

	// mean[j] /= N
	traverser(mean).for_each([&](auto s_m) {
		mean[s_m] *= inv_float_n;
	});

	// ------------------------------------------------------------------------
	// 2) stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	//    if stddev[j] <= eps then stddev[j] = 1.0
	//
	//    Instead of storing stddev[j] itself, we store:
	//       stddev[j] := 1 / (sqrt(N) * stddev[j])
	//    which is exactly the factor by which we will scale in step 3.
	// ------------------------------------------------------------------------

	// stddev[j] = 0
	traverser(stddev).for_each([&](auto s_m) {
		stddev[s_m] = zero;
	});

	// Accumulate squared differences in row-major order
	traverser(data, mean, stddev).for_each([&](auto s_nm) {
		num_t diff = data[s_nm] - mean[s_nm]; // mean ignores 'n'
		stddev[s_nm] += diff * diff;
