	traverser(stddev).for_each([&](auto s_m) {
		// variance estimate: (1/N) * sum (diff^2)
		num_t var_j   = stddev[s_m] * inv_float_n;
		num_t sigma_j = SQRT_FUN(var_j);

		// Original semantics: clamp small standard deviations to 1.0
		if (sigma_j <= eps) {
			// scaling factor = 1 / (sqrt(N) * 1)
			stddev[s_m] = inv_sqrt_n;
		} else {
			// scaling factor = 1 / (sqrt(N) * sigma_j)
			stddev[s_m] = inv_sqrt_n / sigma_j;
		}
	});

	// ------------------------------------------------------------------------
	// 3) Center and scale the column vectors:
	//      data[i][j] = (data[i][j] - mean[j]) / (sqrt(N) * stddev_orig[j])
	//    With the new meaning of stddev[j] as the scaling factor, this becomes:
	//      data[i][j] = (data[i][j] - mean[j]) * stddev[j]
	// ------------------------------------------------------------------------

	traverser(data, mean, stddev).for_each([&](auto s_nm) {
		data[s_nm] = (data[s_nm] - mean[s_nm]) * stddev[s_nm];
	});

	// ------------------------------------------------------------------------
	// 4) Compute the m x m correlation matrix:
	//
	//    After step 3, each column has zero mean and unit norm, so the
	//    correlation is:
	//        corr[i][j] = sum_k data[k][i] * data[k][j]
	//
	//    We keep the original triangular scheme:
	//      - corr[i][i] = 1.0
	//      - for j > i:
	//            corr[i][j] = sum_k ...
	//            corr[j][i] = corr[i][j]
	//
	//    To align feature indices with corr's layout (dims 'p' and 'q'),
	//    we create renamed views of `data`:
	//       data_p: dims 'n', 'p'
	//       data_q: dims 'n', 'q'
	// ------------------------------------------------------------------------

	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

