	// Dimensions in play: 'n', 'p', 'q'.
	//
	// for p in 0..M-1:
	//   corr[p][p] = 1.0;
	//   for q in 0..M-1:
	//     if q > p:
	//       corr[p][q] = sum_n data[n][p] * data[n][q];
	//       corr[q][p] = corr[p][q];
	noarr::traverser(data_p, data_q, corr).template for_dims<'p'>([&](auto trav_p) {
		auto state_p = trav_p.state();
		std::size_t i = noarr::get_index<'p'>(state_p);

		// Diagonal element corr[i][i] = 1.0
		auto diag_state = noarr::idx<'p', 'q'>(i, i);
		corr[diag_state] = one;

		// Now handle all q for this fixed p
		trav_p.template for_dims<'q'>([&](auto trav_pq) {
			auto state_pq = trav_pq.state();
			std::size_t j = noarr::get_index<'q'>(state_pq);

			if (j > i) {
				// Start accumulation for corr[i][j]
				corr[state_pq] = zero;

				// Sum over 'n' (rows). trav_pq has 'p' and 'q' fixed, 'n' free.
				trav_pq.for_each([&](auto state_n) {
					corr[state_pq] += data_p[state_n] * data_q[state_n];
				});

				// Symmetry: corr[j][i] = corr[i][j]
				auto state_qp = noarr::idx<'p', 'q'>(j, i);
				corr[state_qp] = corr[state_pq];
			}
		});
	});

#pragma endscop
}

